DROP TABLE IF EXISTS price_audit;
DROP TABLE IF EXISTS items;
CREATE TABLE items (id INTEGER PRIMARY KEY, name TEXT, price REAL);
CREATE TABLE price_audit (
  id INTEGER PRIMARY KEY,
  item_id INTEGER,
  old_price REAL,
  new_price REAL,
  changed_at TEXT DEFAULT CURRENT_TIMESTAMP
);
INSERT INTO items (name, price) VALUES ('Sticker Pack', 5.0);

cells.source:
DROP TRIGGER IF EXISTS trg_items_price;
CREATE TRIGGER trg_items_price
AFTER UPDATE OF price ON items
FOR EACH ROW
WHEN OLD.price <> NEW.price
BEGIN
  INSERT INTO price_audit (item_id, old_price, new_price)
  VALUES (OLD.id, OLD.price, NEW.price);
END;

UPDATE items SET price = 6.5 WHERE name = 'Sticker Pack';
SELECT i.name, a.old_price, a.new_price, a.changed_at
FROM price_audit AS a
JOIN items AS i ON i.id = a.item_id;

